insert into public.legal_precedents (office_id, court_name, reference_number, decided_on, classification, title, summary, principle_text, source_url, source_version, is_verified)
values
  (null, 'محكمة التمييز - الأحوال الشخصية والأسرة', '32/2006', date '2006-06-21', 'أحوال شخصية، نفقة، حضانة، إثبات', 'الطعن رقم 32 لسنة 2006 تمييز أحوال شخصية', 'حكم منشور يتناول التفريق للشقاق، نفقة الأبناء، الحضانة، واليمين الحاسمة.', 'نفقة الولد واجبة على أبيه حتى يبلغ السن التي يستطيع أن يتكسب بها أمثاله، وتشمل نفقات الدراسة ما دام الأب قادراً عليها. كما يجوز توجيه اليمين الحاسمة في واقعة غير مخالفة للنظام العام ومتعلقة بمن وجهت إليه.', 'https://www.almeezan.qa/RulingPage.aspx?id=238&language=ar', 'بوابة الميزان - صفحة الحكم المنشورة', true),
  (null, 'محكمة التمييز - الدائرة المدنية والتجارية', '65/2006', date '2006-12-05', 'إثبات، يمين متممة، مقاولات', 'الطعن رقم 65 لسنة 2006 تمييز مدني', 'حكم منشور يوضح طبيعة اليمين المتممة وسلطة المحكمة في تقديرها ضمن أدلة الإثبات.', 'اليمين المتممة إجراء يتخذه القاضي من تلقاء نفسه لتحري الحقيقة، وله حرية تعيين من توجه إليه وتقدير نتيجتها لأنها دليل تكميلي محدود القوة.', 'https://www.almeezan.qa/RulingPage.aspx?id=283&language=ar', 'بوابة الميزان - صفحة الحكم المنشورة', true),
  (null, 'محكمة التمييز - الدائرة المدنية والتجارية', '57/2007', date '2008-01-01', 'عمل، إثبات، خبرة، سريان القانون', 'الطعن رقم 57 لسنة 2007 تمييز مدني', 'حكم منشور في منازعة عمل يعالج سريان القانون زمنياً، اليمين الحاسمة، وتقدير تقرير الخبير.', 'الأصل أن القانون الجديد لا يسري على العلاقات القانونية وآثارها الناشئة قبل نفاذه ما لم يرد نص بخلاف ذلك. كما يشترط في اليمين الحاسمة تحديد الواقعة وصيغتها بوضوح، وللمحكمة سلطة تقدير تقرير الخبير.', 'https://www.almeezan.qa/RulingPage.aspx?id=396&language=ar', 'بوابة الميزان - صفحة الحكم المنشورة', true)
